"use client";

import "../../styles/teum-base.css";
import "../../styles/components/funnel.css";
import type { CSSProperties, HTMLAttributes, ReactNode } from "react";
import { formatAnalyticsValue } from "../../lib/analytics";
import { cn } from "../../lib/cn";

export type FunnelStage = {
  id: string;
  label: string;
  value: number;
  detail?: ReactNode;
};

export type FunnelProps = Omit<HTMLAttributes<HTMLOListElement>, "onSelect"> & {
  label: string;
  stages: readonly FunnelStage[];
  formatter?: (value: number, stage: FunnelStage) => string;
  selectedId?: string;
  onSelect?: (stage: FunnelStage) => void;
};

export function Funnel({ label, stages, formatter = (value) => formatAnalyticsValue(value), selectedId, onSelect, className, ...props }: FunnelProps) {
  const baseline = Math.max(1, stages[0]?.value ?? 0, ...stages.map((stage) => stage.value));
  return (
    <ol className={cn("teum-funnel", className)} aria-label={label} {...props}>
      {stages.map((stage, index) => {
        const previous = stages[index - 1]?.value;
        const conversion = index === 0 || !previous ? null : stage.value / previous * 100;
        const width = Math.max(0.08, Math.min(1, stage.value / baseline));
        const body = <>
          <span className="teum-funnel__heading"><strong>{stage.label}</strong><b>{formatter(stage.value, stage)}</b></span>
          <span className="teum-funnel__track" aria-hidden="true"><i style={{ "--teum-funnel-progress": width } as CSSProperties} /></span>
          <span className="teum-funnel__meta">{conversion === null ? "Entry" : `${conversion.toFixed(1)}% from previous`}{stage.detail && <small>{stage.detail}</small>}</span>
        </>;
        return <li key={stage.id}>{onSelect ? <button type="button" aria-pressed={stage.id === selectedId} onClick={() => onSelect(stage)}>{body}</button> : <div>{body}</div>}</li>;
      })}
    </ol>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-funnel { display: grid; min-width: 0; gap: 2px; margin: 0; padding: 0; list-style: none; }

.teum-funnel { gap: 4px; }

.teum-funnel li > div,
.teum-funnel li > button { display: grid; width: 100%; gap: 5px; padding: 8px; border: 0; border-radius: 8px; background: transparent; color: inherit; font: inherit; text-align: left; }

.teum-funnel li > button { cursor: pointer; }

.teum-funnel__heading,
.teum-funnel__meta { display: flex; align-items: center; justify-content: space-between; gap: 12px; }

.teum-funnel__heading strong { font-size: var(--teum-type-ui); font-weight: 570; }

.teum-funnel__heading b { font-size: var(--teum-type-ui); font-variant-numeric: tabular-nums; font-weight: 590; }

.teum-funnel__track { height: 7px; overflow: hidden; border-radius: 999px; background: var(--teum-bg-subtle); }

.teum-funnel__track i { display: block; width: calc(var(--teum-funnel-progress) * 100%); height: 100%; border-radius: inherit; background: var(--teum-fg-default); }

.teum-funnel__meta { color: var(--teum-fg-subtle); font-size: var(--teum-type-metadata); }

.teum-funnel__meta small { font-size: inherit; }

.teum-funnel li > button:focus { outline: 0; }

.teum-funnel li > button:focus-visible {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--teum-focus-control) 42%, transparent);
}

@media (hover: hover) and (pointer: fine) {
.teum-funnel li > button:hover { background: var(--teum-hover); color: var(--teum-fg-default); }
}

.teum-funnel li > button:active { transform: scale(.985); }

.teum-funnel li > button[aria-pressed="true"] { background: var(--teum-selected); }
}
